{
  "title": "add-python-version-to-telemetry",
  "request": "Hey, can we include the Python version in every telemetry event? I think adding it to the captured properties would be helpful. Could you update the capture logic in ProductTelemetry to send a `python_version` field?",
  "edits": [
    {
      "path": "browser_use/telemetry/service.py",
      "search": "import logging",
      "replace": "import logging
import sys"
    },
    {
      "path": "browser_use/telemetry/service.py",
      "search": "self._posthog_client.capture(
			distinct_id=self.user_id,
			event=event.name,
			properties={**event.properties, **POSTHOG_EVENT_SETTINGS},
			)",
      "replace": "self._posthog_client.capture(
			distinct_id=self.user_id,
			event=event.name,
			properties={**event.properties, **POSTHOG_EVENT_SETTINGS, "python_version": sys.version},
			)"
    }
  ],
  "test_path": "tests/test_telemetry_capture.py",
  "test": "import sys

from browser_use.telemetry.service import ProductTelemetry

class DummyEvent:
    def __init__(self, name, properties=None):
        self.name = name
        self.properties = properties or {}

class MockPosthogClient:
    def __init__(self):
        self.captured = []
    def capture(self, distinct_id, event, properties):
        self.captured.append({
            "distinct_id": distinct_id,
            "event": event,
            "properties": properties,
        })
    def flush(self):
        pass

def test_capture_includes_python_version(monkeypatch):
    telemetry = ProductTelemetry()
    mock_client = MockPosthogClient()
    # Replace the real client with our mock
    telemetry._posthog_client = mock_client

    dummy = DummyEvent(name="test_event", properties={"foo": "bar"})
    telemetry.capture(dummy)

    assert len(mock_client.captured) == 1
    captured = mock_client.captured[0]
    assert captured["event"] == "test_event"
    # original property should be present
    assert captured["properties"]["foo"] == "bar"
    # python_version should be added and match sys.version
    assert captured["properties"]["python_version"] == sys.version"
}
